// Text animator maths (workstream text-animators): the selector, noise and path functions match the reference
// implementation (EffectCraft, Rust) bit for bit — fixtures generated by scripts/oracles/text-animators — plus
// property tests of the AE behaviour they implement.
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { describe, expect, it } from 'vitest';
import {
	adjustColor,
	arcPositions,
	hsvToRgb,
	modeCombine,
	modeInitial,
	noise1,
	PathMeasure,
	placeOnPath,
	randomOrder,
	rangeValue,
	rgbToHsv,
	roundHalfAway,
	selectorEase,
	shapeValue,
	splitmix,
	substituteCharacter,
	type TextRangeShape,
	type TextSelectorMode,
	wigglyValue,
} from '../src/index.ts';

type Oracle = {
	range: {
		start: number;
		end: number;
		offset: number;
		amount: number;
		shape: TextRangeShape;
		smoothness: number;
		easeHigh: number;
		easeLow: number;
		n: number;
		values: number[];
	}[];
	ease: { high: number; low: number; values: number[] }[];
	splitmix: { x: string; out: string }[];
	randomOrder: { n: number; seed: string; perm: number[] }[];
	noise: { x: number; seed: string; channel: string; v: number }[];
	wiggly: {
		max: number;
		min: number;
		wigglesPerSecond: number;
		correlation: number;
		temporalPhase: number;
		spatialPhase: number;
		lockDimensions: boolean;
		seed: string;
		samples: { t: number; i: number; dim: number; v: number }[];
	}[];
	combine: { mode: TextSelectorMode; initial: number; acc: number; v: number; out: number }[];
	path: {
		samples: {
			s: number;
			p: number[];
			t: number[];
			pr: number[];
			tr: number[];
			place: number[];
			placeFlat: number[];
		}[];
		arcs: { align: 0 | 1 | 2; first: number; last: number; force: boolean; out: number[] }[];
		xs: number[];
	};
};

const oracle = JSON.parse(
	readFileSync(join(import.meta.dirname, 'fixtures/text-selectors-oracle.json'), 'utf8'),
) as Oracle;

describe('text selectors match the reference implementation', () => {
	it('range_value for every shape, ease and smoothness', () => {
		expect(oracle.range.length).toBeGreaterThan(100);
		for (const c of oracle.range) {
			const got = Array.from({ length: c.n }, (_, i) => rangeValue(c, i, c.n));
			got.forEach((v, i) => expect(v).toBeCloseTo(c.values[i]!, 12));
		}
	});
	it('ease high / low', () => {
		for (const c of oracle.ease)
			c.values.forEach((v, i) => expect(selectorEase(i / 10, c.high, c.low)).toBeCloseTo(v, 12));
	});
	it('SplitMix64, Randomize Order permutations, value noise and wiggly are bit-exact', () => {
		for (const c of oracle.splitmix) expect(splitmix(BigInt(c.x)).toString()).toBe(c.out);
		for (const c of oracle.randomOrder) expect(randomOrder(c.n, BigInt(c.seed))).toEqual(c.perm);
		for (const c of oracle.noise) expect(noise1(c.x, BigInt(c.seed), BigInt(c.channel))).toBe(c.v);
		for (const w of oracle.wiggly) {
			const params = { ...w, seed: BigInt(w.seed) };
			for (const s of w.samples) expect(wigglyValue(params, s.t, s.i, s.dim)).toBeCloseTo(s.v, 13);
		}
	});
	it('mode initial values and combine', () => {
		for (const c of oracle.combine) {
			expect(modeInitial(c.mode)).toBe(c.initial);
			expect(modeCombine(c.mode, c.acc, c.v)).toBeCloseTo(c.out, 14);
		}
	});
	it('path measure, placement and arc positions', () => {
		const line = {
			closed: false,
			vertices: [
				{ point: [0, 0] as [number, number], inTangent: [0, 0] as [number, number], outTangent: [0, 0] as [number, number] },
				{ point: [100, 0] as [number, number], inTangent: [0, 0] as [number, number], outTangent: [0, 0] as [number, number] },
				{ point: [100, 50] as [number, number], inTangent: [0, 0] as [number, number], outTangent: [0, 0] as [number, number] },
			],
		};
		const m = new PathMeasure(line, false);
		const r = new PathMeasure(line, true);
		expect(m.length).toBe(150);
		for (const s of oracle.path.samples) {
			const a = m.at(s.s);
			expect(a.point[0]).toBeCloseTo(s.p[0]!, 9);
			expect(a.point[1]).toBeCloseTo(s.p[1]!, 9);
			expect(a.tangent[0]).toBeCloseTo(s.t[0]!, 9);
			expect(a.tangent[1]).toBeCloseTo(s.t[1]!, 9);
			const b = r.at(s.s);
			expect(b.point[0]).toBeCloseTo(s.pr[0]!, 9);
			expect(b.point[1]).toBeCloseTo(s.pr[1]!, 9);
			const pl = placeOnPath(m, s.s, 10, true);
			expect([...pl.point, pl.angle].map((v) => Number(v.toFixed(9)))).toEqual(
				s.place.map((v) => Number(v.toFixed(9))),
			);
			const pf = placeOnPath(m, s.s, 10, false);
			expect([...pf.point, pf.angle].map((v) => Number(v.toFixed(9)))).toEqual(
				s.placeFlat.map((v) => Number(v.toFixed(9))),
			);
		}
		for (const c of oracle.path.arcs)
			expect(arcPositions(oracle.path.xs, [0, 40], c.align, 100, c.first, c.last, c.force)).toEqual(c.out);
	});
});

describe('text selector behaviour (property tests)', () => {
	it('shapes stay within 0…1 and ramps hold outside the range', () => {
		const shapes: TextRangeShape[] = ['square', 'rampUp', 'rampDown', 'triangle', 'round', 'smooth'];
		for (const s of shapes)
			for (let f = -1; f <= 2; f += 0.01) {
				const v = shapeValue(s, f);
				expect(v).toBeGreaterThanOrEqual(0);
				expect(v).toBeLessThanOrEqual(1);
			}
		expect(shapeValue('rampUp', 5)).toBe(1);
		expect(shapeValue('rampDown', -5)).toBe(1);
		expect(shapeValue('triangle', 1.5)).toBe(0);
	});
	it('ease is monotonic for every high/low', () => {
		for (let h = -1; h <= 1; h += 0.25)
			for (let l = -1; l <= 1; l += 0.25) {
				let prev = -Infinity;
				for (let v = 0; v <= 1.0001; v += 0.02) {
					const e = selectorEase(v, h, l);
					expect(e).toBeGreaterThanOrEqual(prev - 1e-12);
					prev = e;
				}
			}
	});
	it('random order is a permutation for every n and seed', () => {
		for (let n = 0; n < 40; n++)
			for (const seed of [0n, 1n, 123456789n]) {
				const p = randomOrder(n, seed);
				expect([...p].sort((a, b) => a - b)).toEqual(Array.from({ length: n }, (_, i) => i));
			}
	});
	it('wiggly is bounded by min / max and smooth in time', () => {
		const w = {
			max: 0.8,
			min: -0.3,
			wigglesPerSecond: 4,
			correlation: 0.3,
			temporalPhase: 0,
			spatialPhase: 0,
			lockDimensions: false,
			seed: 9n,
		};
		for (let i = 0; i < 200; i++) {
			const v = wigglyValue(w, i * 0.071, i % 13, i % 3);
			expect(v).toBeGreaterThanOrEqual(-0.3 - 1e-12);
			expect(v).toBeLessThanOrEqual(0.8 + 1e-12);
		}
		expect(Math.abs(wigglyValue(w, 1, 2, 0) - wigglyValue(w, 1.0005, 2, 0))).toBeLessThan(0.02);
	});
	it('combine always stays within −1…1', () => {
		const modes: TextSelectorMode[] = ['add', 'subtract', 'intersect', 'min', 'max', 'difference'];
		for (const m of modes)
			for (let a = -1; a <= 1; a += 0.1)
				for (let v = -1; v <= 1; v += 0.1) {
					const r = modeCombine(m, a, v);
					expect(Math.abs(r)).toBeLessThanOrEqual(1);
				}
	});
});

describe('character substitution and colour', () => {
	const xf = (charOffset: number, charRange: 'preserveCaseAndDigits' | 'fullUnicode' = 'preserveCaseAndDigits') => ({
		charOffset,
		charValue: null,
		charRange,
	});
	it('Preserve Case & Digits cycles within letters and digits', () => {
		expect(substituteCharacter('a', xf(1))).toBe('b');
		expect(substituteCharacter('z', xf(1))).toBe('a');
		expect(substituteCharacter('A', xf(-1))).toBe('Z');
		expect(substituteCharacter('9', xf(2))).toBe('1');
		expect(substituteCharacter('!', xf(5))).toBeNull();
		expect(substituteCharacter(' ', xf(5))).toBeNull();
		expect(substituteCharacter('a', xf(26))).toBeNull();
	});
	it('Full Unicode moves through code points; Character Value blends towards a code point', () => {
		expect(substituteCharacter('a', xf(1, 'fullUnicode'))).toBe('b');
		expect(substituteCharacter('z', xf(1, 'fullUnicode'))).toBe('{');
		expect(substituteCharacter('a', { charOffset: 0, charValue: [0x41, 1], charRange: 'fullUnicode' })).toBe('A');
		// Half way from 'a' (97) to 'k' (107) = 102 'f'.
		expect(substituteCharacter('a', { charOffset: 0, charValue: [107, 0.5], charRange: 'fullUnicode' })).toBe('f');
		// Surrogate code points are not characters.
		expect(substituteCharacter('a', { charOffset: 0, charValue: [0xd800, 1], charRange: 'fullUnicode' })).toBeNull();
	});
	it('rounds half away from zero like Rust', () => {
		expect(roundHalfAway(2.5)).toBe(3);
		expect(roundHalfAway(-2.5)).toBe(-3);
		expect(roundHalfAway(-2.4)).toBe(-2);
	});
	it('HSV round-trips and colour adjustments', () => {
		for (const c of [
			[1, 0, 0],
			[0.2, 0.6, 0.9],
			[0.5, 0.5, 0.5],
			[0, 0, 0],
		] as [number, number, number][]) {
			const [h, s, v] = rgbToHsv(...c);
			hsvToRgb(h, s, v).forEach((x, i) => expect(x).toBeCloseTo(c[i]!, 9));
		}
		// Hue +120° turns red into green.
		const g = adjustColor([1, 0, 0, 1], null, 0, [120, 0, 0], 100);
		expect(g.map((x) => Number(x.toFixed(6)))).toEqual([0, 1, 0, 1]);
		// RGB weighted by k, opacity multiplies alpha.
		expect(adjustColor([0, 0, 0, 1], [1, 1, 1, 1], 0.5, [0, 0, 0], 50)).toEqual([0.5, 0.5, 0.5, 0.5]);
	});
});
